  @Override File downloadBookPdf()throws Exception{File f=new File(getCacheDir(),"fixture.pdf");android.graphics.pdf.PdfDocument d=new android.graphics.pdf.PdfDocument();for(int i=0;i<2;i++){android.graphics.pdf.PdfDocument.Page p=d.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(300,400,i).create());p.getCanvas().drawText("Fixture PDF "+i,20,40,new android.graphics.Paint());d.finishPage(p);}try(FileOutputStream o=new FileOutputStream(f)){d.writeTo(o);}d.close();return f;}
