  clickWindow("استخدام الكتب المختارة");if(a.selectedSources.isEmpty())chooseFirstListItem();if(a.selectedSources.size()!=1||!"book-first".equals(a.book.getText().toString()))throw new AssertionError("Primary+supplementary selection failed: selected="+a.selectedSources.size()+" book="+a.book.getText()+" course="+a.course.getText()+" materializing="+a.materializing);evidence.add("DIALOG library primary/supplementary confirmation");
