  for(int stage:new int[]{0,1,4}){final int ix=stage;runOnMainSync(()->{a.showStageResumeCapability(ix,a.stageWorkflow(ix),json("{\"resume_available\":true}"));});settle();runOnMainSync(()->a.stageResumeButtons[ix].performClick());settle();}evidence.add("DIALOG generic stage resume capability contracts");
  runOnMainSync(()->{a.catalogFailure=true;a.loadModelCatalog();});settle();if(!a.modelStateLabel.getText().toString().contains("تعذر"))throw new AssertionError("Catalogue failure not visible");closeDialogs();a.catalogFailure=false;runOnMainSync(a::loadModelCatalog);settle();evidence.add("DIALOG catalogue failure visible and refresh recovers");
