  for(int stage=0;stage<7;stage++){final int ix=stage;runOnMainSync(()->{a.modelStage.setSelection(ix);a.filterModelOptions();a.modelAction(false);});settle();runOnMainSync(()->a.modelAction(true));settle();}evidence.add("DEEP model activate/default contracts for all seven stages");
  runOnMainSync(a::configureExternalModel);settle();ArrayList<EditText> fields=new ArrayList<>();ArrayList<View> activeRoots=roots();for(View v:flat(activeRoots.get(activeRoots.size()-1)))if(v instanceof EditText)fields.add((EditText)v);if(fields.size()!=2)throw new AssertionError("Provider configuration fields missing");runOnMainSync(()->{fields.get(0).setText("fixture-text");fields.get(1).setText("fixture-key-nonsecret");});clickWindow("حفظ وفحص");settle();if(a.p.getAll().toString().contains("fixture-key-nonsecret"))throw new AssertionError("Provider key persisted on phone");closeDialogs();evidence.add("DEEP credentials fixture PUT/secret field clear/no local secret persistence");
