  File wave=new File(a.getCacheDir(),"audio-fixture.wav");int samples=16000*5;java.nio.ByteBuffer pcm=java.nio.ByteBuffer.allocate(44+samples*2).order(java.nio.ByteOrder.LITTLE_ENDIAN);pcm.put("RIFF".getBytes("US-ASCII")).putInt(36+samples*2).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(samples*2);try(FileOutputStream out=new FileOutputStream(wave)){out.write(pcm.array());}
