 static void installFixtureConnections(){try{java.net.URL.setURLStreamHandlerFactory(protocol->{if(!"https".equals(protocol)&&!"http".equals(protocol))return null;return new java.net.URLStreamHandler(){protected java.net.URLConnection openConnection(java.net.URL u){return new java.net.HttpURLConnection(u){ByteArrayOutputStream sent=new ByteArrayOutputStream();public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public OutputStream getOutputStream(){return sent;}public int getResponseCode(){return 200;}public InputStream getInputStream()throws IOException{try{if(activeFixture==null)throw new IOException("No active fixture; external network forbidden");String path=url.getPath()+(url.getQuery()==null?"":"?"+url.getQuery());JSONObject body=sent.size()==0?null:new JSONObject(sent.toString("UTF-8"));JSONObject response=activeFixture.req(method,path,body);if(path.endsWith("/results/export")){ByteArrayOutputStream output=new ByteArrayOutputStream();try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(output)){zip.putNextEntry(new java.util.zip.ZipEntry("lesson.md"));zip.write("Fixture source and questions".getBytes("UTF-8"));zip.closeEntry();}return new ByteArrayInputStream(output.toByteArray());}return new ByteArrayInputStream(response.toString().getBytes("UTF-8"));}catch(Exception e){throw new IOException(e);}}};}};});}catch(Error e){if(!e.getMessage().contains("factory already defined"))throw e;}}
